<?php
    require_once(__DIR__ . "/GetTripHandler.php");

    class UpdateTripHandler extends Handler {
        public function handle($input) {
            global $tripService, $databaseProvider;

            $response = (new GetTripHandler())
                ->handle(array(
                    "tripId" => $input["tripId"]));
            if ($response["code"] != 200) {
                return $response;
            }
    
            if (isset($input["start"])) {
                $tripService->moveTrip($input["tripId"], $input["start"]);
            }
            if (isset($input["mainHighlightId"])) {
                $tripService->updateTripMainHighlight($input["tripId"], $input["mainHighlightId"]);
            }
            if (isset($input["name"])) {
                $tripService->updateTripName($input["tripId"], $input["name"]);
            }

            
            $databaseProvider->materializeViews();
            return (new GetTripHandler())
                ->handle(array(
                    "tripId" => $input["tripId"]));
        }

        public function getRequiredRole() {
            return "ADMIN";
        }
        
        public function isProtected() {
            return TRUE;
        }

        public function getTag() {
            return "Trips";
        }

        public function getPath() {
            return "/trips/{tripId}";
        }

        public function getParameters() {
            return array(
                $this->createPathParameter("tripId", "integer", 128));
        }

        public function getMethod() {
            return "PATCH";
        }
        
        public function getShortDescription() {
            return "Update a trip with the specified identifier";
        }
        
        public function getLongDescription() {
            return "Updates a trip with the specified identifier.";
        }
        
        public function getRequestExamples() {
            return array(
                $this->createRequestExample("Update trip name", '{"name":"Východní Itálie"}'),
                $this->createRequestExample("Update trip start", '{"start":1724666400}'),
                $this->createRequestExample("Update trip main highlight", '{"mainHighlightId":1}'));
        }

